import React, { useEffect, useState } from "react";
import axios from "axios";

function JoinExam() {
  const [exams, setExams] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const token = localStorage.getItem("token");

  // Lädt verfügbare Klausuren vom Backend
  useEffect(() => {
    if (!token) {
      setError("Kein Token vorhanden. Bitte erneut einloggen.");
      setLoading(false);
      return;
    }

    axios
      .get("http://127.0.0.1:8000/api/students/exams/", {
        headers: { Authorization: `Token ${token}` },
      })
      .then((res) => {
        setExams(res.data);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Exam-Fehler:", err);
        setError("Fehler beim Laden der Klausuren.");
        setLoading(false);
      });
  }, [token]);

  // Funktion: Student tritt einer Klausur bei
  const joinExam = async (examId) => {
    try {
      const res = await axios.post(
        `http://127.0.0.1:8000/api/students/exams/${examId}/join/`,
        {},
        { headers: { Authorization: `Token ${token}` } }
      );
      alert(res.data.message);
    } catch (err) {
      console.error("Join-Fehler:", err);
      alert("Fehler beim Beitreten zur Klausur.");
    }
  };

  // Funktion: Logout
  const handleLogout = () => {
    localStorage.removeItem("token");
    window.location.href = "/"; // zurück zur Login-Seite
  };

  // UI während des Ladens oder bei Fehler
  if (loading) return <p>Lade Klausuren...</p>;
  if (error)
    return (
      <div style={{ padding: "20px" }}>
        <p style={{ color: "red" }}>{error}</p>
        <button onClick={handleLogout}>Zurück zum Login</button>
      </div>
    );

  return (
    <div style={{ padding: "20px", fontFamily: "Arial, sans-serif" }}>
      {/* Kopfbereich mit Logout */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: "20px",
        }}
      >
        <h2>Verfügbare Klausuren</h2>
        <button
          onClick={handleLogout}
          style={{
            backgroundColor: "#c62828",
            color: "white",
            border: "none",
            padding: "8px 16px",
            borderRadius: "6px",
            cursor: "pointer",
            fontWeight: "bold",
          }}
        >
          Abmelden
        </button>
      </div>

      {/* Klausurliste */}
      {exams.length === 0 ? (
        <p>Keine Klausuren verfügbar.</p>
      ) : (
        <ul style={{ listStyleType: "none", padding: 0 }}>
          {exams.map((exam) => (
            <li
              key={exam.id}
              style={{
                backgroundColor: "#f5f5f5",
                marginBottom: "10px",
                padding: "10px",
                borderRadius: "8px",
              }}
            >
              <strong>{exam.title}</strong> –{" "}
              {new Date(exam.date).toLocaleString("de-DE")}
              <button
                onClick={() => joinExam(exam.id)}
                style={{
                  marginLeft: "10px",
                  backgroundColor: "#1976d2",
                  color: "white",
                  border: "none",
                  padding: "5px 12px",
                  borderRadius: "5px",
                  cursor: "pointer",
                }}
              >
                Beitreten
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

export default JoinExam;
